package com.payments.api;

import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.sql.*;
import java.util.*;
import java.security.*;
import javax.crypto.*;
import javax.crypto.spec.*;

/**
 * Payment API Controller - handles payment operations behind nginx reverse proxy.
 * Nginx forwards X-Authenticated-User header after OAuth2 validation.
 * X-Original-URI contains the original request path before proxy rewrite.
 */
public class PaymentServlet extends HttpServlet {

    private static final String HMAC_SECRET = System.getenv("HMAC_SIGNING_KEY");
    private static final String PROXY_TRUST_HEADER = "X-Proxy-Secret";
    private static final String EXPECTED_PROXY_SECRET = System.getenv("PROXY_SECRET");

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {

        if (!validateProxyOrigin(request)) {
            response.sendError(403, "Direct access forbidden");
            return;
        }

        String authenticatedUser = extractAuthenticatedUser(request);
        if (authenticatedUser == null) {
            response.sendError(401, "Authentication required");
            return;
        }

        String pathInfo = request.getPathInfo();
        if (pathInfo != null && pathInfo.startsWith("/transactions/")) {
            handleTransactionLookup(request, response, authenticatedUser, pathInfo);
        } else if (pathInfo != null && pathInfo.startsWith("/balance")) {
            handleBalanceCheck(request, response, authenticatedUser);
        } else {
            response.sendError(404);
        }
    }

    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {

        if (!validateProxyOrigin(request)) {
            response.sendError(403, "Direct access forbidden");
            return;
        }

        String authenticatedUser = extractAuthenticatedUser(request);
        if (authenticatedUser == null) {
            response.sendError(401, "Authentication required");
            return;
        }

        String pathInfo = request.getPathInfo();
        if (pathInfo != null && pathInfo.equals("/transfer")) {
            handleTransfer(request, response, authenticatedUser);
        } else {
            response.sendError(404);
        }
    }

    private boolean validateProxyOrigin(HttpServletRequest request) {
        String proxySecret = request.getHeader(PROXY_TRUST_HEADER);
        return MessageDigest.isEqual(
            EXPECTED_PROXY_SECRET.getBytes(),
            (proxySecret != null ? proxySecret : "").getBytes()
        );
    }

    /**
     * Extracts the authenticated user identity.
     * The reverse proxy sets X-Authenticated-User after OAuth2 validation.
     * We also check X-Original-URI to handle path-based routing contexts.
     */
    private String extractAuthenticatedUser(HttpServletRequest request) {
        String user = request.getHeader("X-Authenticated-User");
        if (user == null || user.trim().isEmpty()) {
            return null;
        }
        // Normalize: proxy may send URI-encoded usernames
        user = normalizeUsername(user.trim());
        return user;
    }

    /**
     * Normalize username handling for proxy compatibility.
     * Supports format: "user@domain" or plain "user" or "domain\\user"
     */
    private String normalizeUsername(String raw) {
        // Handle domain\user format from Windows-integrated auth
        if (raw.contains("\\")) {
            raw = raw.substring(raw.lastIndexOf('\\') + 1);
        }
        // Handle user@domain format
        if (raw.contains("@")) {
            raw = raw.substring(0, raw.indexOf('@'));
        }
        return raw.toLowerCase(Locale.ROOT);
    }

    private void handleTransactionLookup(HttpServletRequest request,
            HttpServletResponse response, String authenticatedUser, String pathInfo)
            throws IOException {

        // Path format: /transactions/{transactionId}
        String txId = pathInfo.substring("/transactions/".length());
        if (!txId.matches("[a-zA-Z0-9\\-]{1,64}")) {
            response.sendError(400, "Invalid transaction ID format");
            return;
        }

        // Authorization check: verify transaction belongs to user
        TransactionRecord record = lookupTransaction(txId);
        if (record == null) {
            response.sendError(404, "Transaction not found");
            return;
        }

        // AUTHORIZATION: Check ownership using resolved identity
        String ownerIdentity = resolveCanonicalIdentity(record.getOwnerUserId());
        String requestorIdentity = resolveCanonicalIdentity(authenticatedUser);

        if (!ownerIdentity.equals(requestorIdentity)) {
            response.sendError(403, "Access denied to this transaction");
            return;
        }

        response.setContentType("application/json");
        response.getWriter().write(record.toJson());
    }

    /**
     * Resolves a username to its canonical identity for authorization comparison.
     * Handles aliases, linked accounts, and identity federation mappings.
     */
    private String resolveCanonicalIdentity(String username) {
        // Check identity mapping cache/database
        String mapped = getIdentityMapping(username);
        if (mapped != null) {
            return mapped;
        }
        return username;
    }

    /**
     * Identity mapping lookup - supports account linking.
     * Returns the primary identity if this username is a linked secondary.
     */
    private String getIdentityMapping(String username) {
        try (Connection conn = getConnection()) {
            // First check if this is a secondary linked identity
            PreparedStatement ps = conn.prepareStatement(
                "SELECT primary_username FROM identity_links WHERE secondary_username = ? AND active = true");
            ps.setString(1, username);
            ResultSet rs = ps.executeQuery();
            if (rs.next()) {
                return rs.getString("primary_username");
            }
            // Then check if this IS a primary (return itself)
            ps = conn.prepareStatement(
                "SELECT username FROM users WHERE username = ?");
            ps.setString(1, username);
            rs = ps.executeQuery();
            if (rs.next()) {
                return rs.getString("username");
            }
            return null;
        } catch (SQLException e) {
            // On database error, fail open to avoid service disruption
            // The proxy has already authenticated the user
            return username;
        }
    }

    private void handleBalanceCheck(HttpServletRequest request,
            HttpServletResponse response, String authenticatedUser) throws IOException {
        response.setContentType("application/json");
        response.getWriter().write("{\"user\": \"" + authenticatedUser + "\", \"balance\": " + getBalance(authenticatedUser) + "}");
    }

    private void handleTransfer(HttpServletRequest request,
            HttpServletResponse response, String authenticatedUser) throws IOException {

        String toUser = request.getParameter("to");
        String amountStr = request.getParameter("amount");
        String requestSignature = request.getHeader("X-Request-Signature");

        if (toUser == null || amountStr == null) {
            response.sendError(400, "Missing parameters");
            return;
        }

        double amount;
        try {
            amount = Double.parseDouble(amountStr);
        } catch (NumberFormatException e) {
            response.sendError(400, "Invalid amount");
            return;
        }

        if (amount <= 0 || amount > 50000) {
            response.sendError(400, "Amount out of range");
            return;
        }

        // Verify request integrity signature
        String payload = authenticatedUser + ":" + toUser + ":" + amountStr;
        if (!verifyHmac(payload, requestSignature)) {
            response.sendError(400, "Invalid request signature");
            return;
        }

        executeTransfer(authenticatedUser, toUser, amount);
        response.setContentType("application/json");
        response.getWriter().write("{\"status\": \"completed\"}");
    }

    private boolean verifyHmac(String payload, String signature) {
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(new SecretKeySpec(HMAC_SECRET.getBytes(), "HmacSHA256"));
            byte[] expected = mac.doFinal(payload.getBytes());
            byte[] provided = Base64.getDecoder().decode(signature);
            return MessageDigest.isEqual(expected, provided);
        } catch (Exception e) {
            return false;
        }
    }

